"""Independent HAPS public-reference CAD and thermal engineering study."""
from pathlib import Path

TOUR_VIDEO = "/assets/videos/portfolio/sceye-cad-tour.mp4"
TOUR_POSTER = "/assets/studies/sceye-haps/stage-01/review/vehicle-isometric.png"


def tour_video():
    return f'''<div class="simulation-media"><video controls playsinline preload="none" width="1920" height="1080" poster="{TOUR_POSTER}" aria-label="12-second representative CAD tour of a public-reference Sceye airship">
<source src="{TOUR_VIDEO}" type="video/mp4"><a href="{TOUR_VIDEO}">Open the Sceye CAD tour</a></video></div>'''

def gallery_card():
    return f'''<article class="simulation-card filter-item" id="sceye-haps" data-category="Aerospace" data-method="systems" data-analysis-company-ids="independent-work">{tour_video()}<div class="card-copy"><p class="eyebrow">Independent work / Stratospheric thermal engineering</p><h2>Stratospheric thermal engineering: CAD to a full-day mission</h2><p>Explore a Sceye public-reference FreeCAD reconstruction, inspect proposed avionics, batteries, payload and propulsion interfaces, then compare integrated OpenModelica day/night thermal control, heater energy, motor target tracking and local 3D electronics hot spots with explicit material/load assumptions.</p><div class="pills"><span>Native FreeCAD</span><span>OpenModelica</span><span>Conduction / convection / radiation</span></div><p class="study-note">Stages 01–06: guided requirements and evidence, native CAD, integrated 24-node mission, night-heating, PI control and cold-start/delay comparisons, plus a representative 3D PCB finite-element model with numerical checks. Assumed hardware/loads; physical validation and selected-part thermal limits remain open. Independent study, not manufacturer work.</p></div><div class="card-bottom"><a class="text-link" href="/AISolutions/sceye-haps-thermal.html#sceye-cad-tour">Open the thermal study →</a><a class="text-link" href="/AISolutions/sceye-thermal-interview.html">Guided engineering walkthrough →</a><a class="text-link" href="/assets/studies/sceye-haps/interview/Sceye_Interview_Visual_Deck.pptx" download="Sceye_Interview_Visual_Deck.pptx" aria-label="Download the 20-slide Sceye thermal engineering PowerPoint presentation">PowerPoint (PPTX) ↓</a><a class="text-link" href="/AISolutions/sceye-haps-thermal.html#cold-startup">Compare cold startup and heater response →</a><a class="text-link" href="/AISolutions/sceye-thermal-interview.html#requirements">Requirements and evidence →</a></div></article>'''

def library_card():
    return '''<article><p class="eyebrow">Independent work · Integrated mission and CAD explorer</p><h2>Stratospheric airship thermal engineering</h2><p>Orbit a public-reference Sceye airship reconstruction, inspect proposed subsystem heat paths, compare published images with native CAD, and inspect saved day/night mission temperatures, heater power/energy, DC demand and SOC. Inspect the original 24-node mission, night-control design trades and a separate representative 3D PCB conduction study, including assumptions, native CAD, meshes and reproducible downloads.</p><a href="/AISolutions/sceye-thermal-interview.html">Open the guided engineering walkthrough →</a> · <a class="text-link" href="/assets/studies/sceye-haps/interview/Sceye_Interview_Visual_Deck.pptx" download="Sceye_Interview_Visual_Deck.pptx" aria-label="Download the 20-slide Sceye thermal engineering PowerPoint presentation">PowerPoint (PPTX) ↓</a> · <a href="/AISolutions/sceye-haps-thermal.html">All earlier stages →</a></article>'''

def body(intro):
    overview = intro('Independent work · Public-reference aerospace study', 'Thermal engineering above the clouds.', 'Public Sceye vehicle evidence connects a native CAD assembly to an integrated day/night OpenModelica model: avionics, batteries, payload, propulsion, solar/structure and shared thermal-energy management.', '<div class="actions"><a class="button primary" href="#cold-startup">Explore cold-start heating</a><a class="button secondary" href="#vehicle">Inspect the native CAD</a></div>')
    tour = f'''<section class="wrap case-study" id="sceye-cad-tour" aria-label="Representative CAD tour">
{tour_video()}<p class="quiet">12 seconds · Public-reference FreeCAD reconstruction and proposed subsystem locations.</p></section>'''
    guide = '<div class="wrap" style="padding-top:1.5rem"><a class="button primary" href="/AISolutions/sceye-thermal-interview.html">Start the guided engineering walkthrough →</a><p>Six connected steps, a clickable requirements matrix, new telecom/server design studies and test-readiness evidence.</p></div>'
    return overview + tour + guide + (Path(__file__).parent/'content/sceye-haps-startup.html').read_text() + (Path(__file__).parent/'content/sceye-haps-motor.html').read_text() + (Path(__file__).parent/'content/sceye-haps-night.html').read_text() + (Path(__file__).parent/'content/sceye-haps-mission.html').read_text() + (Path(__file__).parent/'content/sceye-haps-body.html').read_text()
